// =========================================================================
// 04_MYTHIC_VICTINI_VICTORY_STAR - Modern HTML5 Canvas 2D Implementation
// 100% Anatomical Likeness & High-End 3D Pop Mart Vinyl Aesthetic
// Organic Micro-Physics: 5% Squash & Stretch, Flap Lag 0.45 rad, Ear Flames
// =========================================================================
function drawVictiniVictoryStar(ctx, cx, cy, scale, t) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  // 1. Organic Micro-Physics Kinematics
  const breathFreq = 2.4; // Tần số nhịp thở/nhún nhảy năng lượng tích cực
  const breathPhase = t * breathFreq;
  const breathSin = Math.sin(breathPhase);

  // Squash & Stretch 5% bảo toàn thể tích
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const bounceY = -Math.abs(breathSin) * 4.0; // Độ nảy nhún đàn hồi
  const by = bounceY; // base Y offset for body

  // Đôi cánh nhỏ sau lưng vỗ nhịp trễ pha Delta Phi = 0.45 rad
  const wLag = breathPhase - 0.45;
  const wFlapL = Math.sin(wLag) * 5.0;
  const wFlapR = Math.sin(wLag + 0.15) * 5.0;

  // Lửa chóp tai bập bùng tần số cao
  const flameF1 = Math.sin(t * 14.0) * 2.5 + Math.cos(t * 24.0) * 1.5;
  const flameF2 = Math.cos(t * 16.0) * 2.2 + Math.sin(t * 26.0) * 1.6;

  // Nhịp chớp mắt 3.5s (interval 3500ms, duration 140ms)
  const blinkCycle = (t * 1000) % 3500;
  const blink = blinkCycle < 140;

  // 2. LAYER 0: BÓNG TIẾP XÚC MẶT ĐẤT CO GIÃN (Dynamic Ground Contact Shadow)
  ctx.save();
  const shadowScale = (1.0 - bounceY * 0.05);
  const shadowGrad = ctx.createRadialGradient(0, 52, 4, 0, 52, 42 * sX * shadowScale);
  shadowGrad.addColorStop(0, "rgba(18, 22, 30, 0.65)");
  shadowGrad.addColorStop(0.5, "rgba(22, 26, 36, 0.35)");
  shadowGrad.addColorStop(1, "rgba(22, 26, 36, 0.0)");
  ctx.fillStyle = shadowGrad;
  ctx.beginPath();
  ctx.ellipse(0, 52, 42 * sX * shadowScale, 9.5 * sX * shadowScale, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // 3. LAYER 1: ĐÔI CÁNH LÔNG VŨ PHÍA SAU (Feathered Wing Tails with Phase Lag)
  // Cánh trái (viewer's left)
  ctx.save();
  ctx.translate(-18, by + 18);
  ctx.rotate((-15 + wFlapL * 1.5) * Math.PI / 180);
  for (let i = 0; i < 3; i++) {
    const lobeAngle = -0.35 + i * 0.32;
    const lobeLen = 22 + i * 3;
    ctx.save();
    ctx.rotate(lobeAngle);
    const wingGrad = ctx.createLinearGradient(0, 0, -lobeLen, 0);
    wingGrad.addColorStop(0, "#FCE39E");
    wingGrad.addColorStop(0.7, "#F6DC92");
    wingGrad.addColorStop(1, "#DAB052");
    ctx.fillStyle = wingGrad;
    ctx.beginPath();
    ctx.ellipse(-lobeLen * 0.5, 0, lobeLen * 0.55, 4.2, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#C99A3A";
    ctx.lineWidth = 0.8;
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();

  // Cánh phải (viewer's right)
  ctx.save();
  ctx.translate(16, by + 16);
  ctx.rotate((15 + wFlapR * 1.5) * Math.PI / 180);
  for (let i = 0; i < 3; i++) {
    const lobeAngle = -0.35 + i * 0.32;
    const lobeLen = 22 + i * 3;
    ctx.save();
    ctx.rotate(lobeAngle);
    const wingGrad = ctx.createLinearGradient(0, 0, lobeLen, 0);
    wingGrad.addColorStop(0, "#FCE39E");
    wingGrad.addColorStop(0.7, "#F6DC92");
    wingGrad.addColorStop(1, "#DAB052");
    ctx.fillStyle = wingGrad;
    ctx.beginPath();
    ctx.ellipse(lobeLen * 0.5, 0, lobeLen * 0.55, 4.2, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#C99A3A";
    ctx.lineWidth = 0.8;
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();

  // 4. LAYER 2: ĐÔI TAI NHỌN CHỮ V KHỔNG LỒ (Iconic Giant V-Ears 3D Vinyl)
  // Tai trái (Viewer's Left - Upward Vertical Ear)
  ctx.save();
  ctx.translate(0, by);
  ctx.beginPath();
  ctx.moveTo(-18, -16);
  ctx.bezierCurveTo(-22, -45, -24, -75, -23, -98);
  ctx.lineTo(2, -26);
  ctx.closePath();
  const earGradL = ctx.createLinearGradient(-24, -98, 0, -20);
  earGradL.addColorStop(0, "#FF844B");
  earGradL.addColorStop(0.3, "#F35824");
  earGradL.addColorStop(1, "#D63F10");
  ctx.fillStyle = earGradL;
  ctx.fill();
  ctx.strokeStyle = "#B83208";
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // Highlight sống tai
  ctx.strokeStyle = "rgba(255, 235, 200, 0.6)";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-18, -18);
  ctx.lineTo(-23, -96);
  ctx.stroke();

  // Lòng tai nhung đen
  ctx.beginPath();
  ctx.moveTo(-15, -25);
  ctx.lineTo(-20, -78);
  ctx.lineTo(-4, -28);
  ctx.closePath();
  const innerGradL = ctx.createLinearGradient(-20, -78, -10, -25);
  innerGradL.addColorStop(0, "#2C282A");
  innerGradL.addColorStop(0.5, "#1A1819");
  innerGradL.addColorStop(1, "#0D0C0D");
  ctx.fillStyle = innerGradL;
  ctx.fill();

  // Viền kem 3D mép tai
  ctx.strokeStyle = "#FFF4D1";
  ctx.lineWidth = 1.0;
  ctx.beginPath();
  ctx.moveTo(-23, -98);
  ctx.lineTo(-17, -20);
  ctx.stroke();
  ctx.restore();

  // Tai phải (Viewer's Right - Diagonal Outward Ear)
  ctx.save();
  ctx.translate(0, by);
  ctx.beginPath();
  ctx.moveTo(2, -26);
  ctx.bezierCurveTo(32, -38, 62, -52, 92, -64);
  ctx.bezierCurveTo(62, -35, 38, -18, 16, -14);
  ctx.closePath();
  const earGradR = ctx.createLinearGradient(0, -25, 92, -64);
  earGradR.addColorStop(0, "#D63F10");
  earGradR.addColorStop(0.6, "#F35824");
  earGradR.addColorStop(1, "#FF844B");
  ctx.fillStyle = earGradR;
  ctx.fill();
  ctx.strokeStyle = "#B83208";
  ctx.lineWidth = 1.2;
  ctx.stroke();

  ctx.strokeStyle = "rgba(255, 235, 200, 0.7)";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(3, -25);
  ctx.lineTo(90, -63);
  ctx.stroke();

  // Lòng tai nhung đen
  ctx.beginPath();
  ctx.moveTo(6, -24);
  ctx.lineTo(72, -55);
  ctx.lineTo(20, -18);
  ctx.closePath();
  const innerGradR = ctx.createLinearGradient(20, -18, 72, -55);
  innerGradR.addColorStop(0, "#0D0C0D");
  innerGradR.addColorStop(0.5, "#1A1819");
  innerGradR.addColorStop(1, "#2C282A");
  ctx.fillStyle = innerGradR;
  ctx.fill();

  ctx.strokeStyle = "#FFF4D1";
  ctx.lineWidth = 1.0;
  ctx.beginPath();
  ctx.moveTo(92, -64);
  ctx.lineTo(18, -14);
  ctx.stroke();
  ctx.restore();

  // Hào quang lửa chiến thắng trên 2 chóp tai
  ctx.save();
  ctx.translate(-23, by - 98);
  const fGrad1 = ctx.createRadialGradient(0, 0, 1, 0, -6 + flameF1, 14);
