function drawSapphireEye(ctx, ex, ey, rx, ry, rot, blink) {
  ctx.save();
  ctx.translate(ex, ey);
  ctx.rotate(rot);

  if (blink) {
    ctx.strokeStyle = "#091B2C";
    ctx.lineWidth = 2.4;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(0, 2, rx * 0.9, Math.PI * 0.15, Math.PI * 0.85);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(rx * 0.8, 4);
    ctx.lineTo(rx * 1.1, 1);
    ctx.stroke();
  } else {
    // 1. Viền ngoài & Hốc mắt sâu
    ctx.beginPath();
    ctx.ellipse(0, 0, rx, ry, 0, 0, Math.PI * 2);
    ctx.fillStyle = "#091B2C";
    ctx.fill();

    // 2. Tròng mắt Sapphire đa tầng
    const irisGrad = ctx.createLinearGradient(0, -ry, 0, ry);
    irisGrad.addColorStop(0, "#033B75");
    irisGrad.addColorStop(0.35, "#0556A5");
    irisGrad.addColorStop(0.75, "#2FB4F8");
    irisGrad.addColorStop(1, "#7EE3FB");
    ctx.beginPath();
    ctx.ellipse(0, 0, rx - 1.2, ry - 1.2, 0, 0, Math.PI * 2);
    ctx.fillStyle = irisGrad;
    ctx.fill();

    // Vòm sáng đáy mắt
    ctx.beginPath();
    ctx.ellipse(0, ry * 0.35, rx * 0.65, ry * 0.45, 0, 0, Math.PI);
    ctx.fillStyle = "rgba(126, 227, 251, 0.55)";
    ctx.fill();

    // 3. 3 ĐIỂM BẮT SÁNG PHA LÊ (3-Point Specular Highlights)
    // Điểm 1: Primary Specular (Bầu dục lớn góc trên phải)
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath();
    ctx.ellipse(rx * 0.22, -ry * 0.35, rx * 0.38, ry * 0.26, -0.2, 0, Math.PI * 2);
    ctx.fill();

    // Điểm 2: Secondary Caustic (Tròn vừa góc dưới trái)
    ctx.fillStyle = "rgba(240, 250, 255, 0.9)";
    ctx.beginPath();
    ctx.arc(-rx * 0.28, ry * 0.35, rx * 0.18, 0, Math.PI * 2);
    ctx.fill();

    // Điểm 3: Tertiary Micro Glint (Hạt pha lê lấp lánh mép phải)
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath();
    ctx.arc(rx * 0.35, ry * 0.12, rx * 0.11, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawVictorySparkle(ctx, x, y, scale, color) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(0, -6);
  ctx.quadraticCurveTo(0, 0, 6, 0);
  ctx.quadraticCurveTo(0, 0, 0, 6);
  ctx.quadraticCurveTo(0, 0, -6, 0);
  ctx.quadraticCurveTo(0, 0, 0, -6);
  ctx.fill();
  ctx.fillStyle = "#FFFFFF";
  ctx.beginPath();
  ctx.arc(0, 0, 1.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}
